      return Response.ok(
        json.encode(Assets.destinations),
        headers: {'Content-Type': 'application/json'},
      );
    });

    router.get('/<id>/activity', (Request request, String id) {
      final list = Assets.activities
          .where((activity) => activity.destinationRef == id)
          .toList();
