class ClientState {
  /// Creates a new instance listening to events and updating the state
  ClientState(this._client);

  CompositeSubscription? _eventsSubscription;

  /// Starts listening to the client events.
  void subscribeToEvents() {
    if (_eventsSubscription != null) {
      cancelEventSubscription();
    }

    _eventsSubscription = CompositeSubscription()
      ..add(
        _client.on().listen((event) {
          // Update the current user only if the event is not a health check.
          if (event.me case final user?) {
            if (event.type != EventType.healthCheck) {
              currentUser = currentUser?.merge(user) ?? user;
            }
          }

          // Update the total unread count.
          if (event.totalUnreadCount case final count?) {
            currentUser = currentUser?.copyWith(totalUnreadCount: count);
          }

          // Update the unread channels count.
          if (event.unreadChannels case final count?) {
            currentUser = currentUser?.copyWith(unreadChannels: count);
          }

          // Update the unread threads count.
          if (event.unreadThreads case final count?) {
            currentUser = currentUser?.copyWith(unreadThreads: count);
          }

          // Update the push preferences.
          if (event.pushPreference case final preferences?) {
            currentUser = currentUser?.copyWith(pushPreferences: preferences);
          }
        }),
      );

    // region CHANNEL EVENTS
    _listenChannelLeft();
    _listenChannelDeleted();
    _listenChannelHidden();
    // endregion

    // region USER EVENTS
    _listenUserUpdated();
    _listenUserMessagesDeleted();
    // endregion

    // region READ EVENTS
    _listenAllChannelsRead();
    // endregion

    // region LOCATION EVENTS
    _listenLocationShared();
    _listenLocationUpdated();
    _listenLocationExpired();
    // endregion

    _startCleaningExpiredLocations();
  }

class ChannelClientState {
  /// Creates a new instance listening to events and updating the state.
  ChannelClientState(
    this._channel,
    ChannelState channelState,
  ) {
    _retryQueue = RetryQueue(
      channel: _channel,
      logger: _client.detachedLogger(
        '🔄 (${generateHash([_channel.cid])})',
      ),
    );

    _channelStateController = BehaviorSubject.seeded(channelState);
    // Update the persistence storage with the seeded channel state.
    _debouncedUpdatePersistenceChannelState.call([channelState]);

    // region TYPING EVENTS
    _listenTypingEvents();
    // endregion

    // region MESSAGE EVENTS
    _listenMessageNew();
    _listenMessageDeleted();
    _listenMessageUpdated();
    // endregion

    // region DRAFT EVENTS
    _listenDraftUpdated();
    _listenDraftDeleted();
    // endregion

    // region REACTION EVENTS
    _listenReactionNew();
    _listenReactionUpdated();
    _listenReactionDeleted();
    // endregion

    // region POLL EVENTS
    _listenPollCreated();
    _listenPollUpdated();
    _listenPollClosed();
    _listenPollAnswerCasted();
    _listenPollVoteCasted();
    _listenPollVoteChanged();
    _listenPollAnswerRemoved();
    _listenPollVoteRemoved();
    // endregion

    // region READ EVENTS
    _listenReadEvents();
    // endregion

    // region CHANNEL EVENTS
    _listenChannelTruncated();
    _listenChannelUpdated();
    _listenChannelMessageCount();
    // endregion

    // region MEMBER EVENTS
    _listenMemberAdded();
    _listenMemberRemoved();
    _listenMemberUpdated();
    _listenMemberBanned();
    _listenMemberUnbanned();
    _listenUserMessagesDeleted();
    // endregion

    // region USER WATCHING EVENTS
    _listenUserStartWatching();
    _listenUserStopWatching();
    // endregion

    // region REMINDER EVENTS
    _listenReminderCreated();
    _listenReminderUpdated();
    _listenReminderDeleted();
    // endregion

    // region LOCATION EVENTS
    _listenLocationShared();
    _listenLocationUpdated();
    _listenLocationExpired();
    // endregion

    _startCleaningStaleTypingEvents();

    _startCleaningStalePinnedMessages();

    _startCleaningExpiredLocations();

    _listenChannelPushPreferenceUpdated();

    final persistenceClient = _client.chatPersistenceClient;
    persistenceClient
        ?.getChannelThreads(_channel.cid!)
        .then((threads) {
          // Load all the threads for the channel from the offline storage.
          if (threads.isNotEmpty) _threads = threads;
        })
        .then((_) => retryFailedMessages());
  }

