abstract class BaseUseCase<IN, OUT> {
  OUT callInternal(IN param);

  Result<OUT> call(IN param) {
    logD("call = $param");
    try {
      final result = callInternal(param);
      return Success(data: result);
    } catch (error) {
      final Exception exception;

      if (error is Exception) {
        exception = error;
      } else {
        exception = UnknownObjectThrownException(object: error);
      }
      return Error(exception: exception);
    }
  }

abstract class BaseUnsafeUseCase<IN, OUT> {
  OUT callInternal(IN param);

  OUT call(IN param) {
    logD("call: param = $param");
    return callInternal(param);
  }

