abstract class BaseRepository {
  /// Creates a [BaseRepository] with the given [exceptionHandler] and
  /// optional [failureMapper].
  ///
  /// Parameters:
  /// - [exceptionHandler]: Handles exception-to-failure conversion
  /// - [failureMapper]: Optional feature-specific mapper for [ServerException]
  const BaseRepository(this.exceptionHandler, [this.failureMapper]);

  /// The exception handler used to convert exceptions to failures.
  @protected
  final ExceptionHandler exceptionHandler;

  /// Optional feature-specific failure mapper.
  ///
  /// If provided, this mapper will be used to convert [ServerException]
  /// to domain-specific failures. If null, defaults to infrastructure failures.
  @protected
  final IExceptionMapper? failureMapper;

  /// Executes a repository operation with automatic exception handling.
  ///
  /// This method wraps the given [operation] with exception handling logic,
  /// converting any thrown exceptions into appropriate [Failure] objects.
  ///
  /// If a [failureMapper] was provided during construction, it will be used
  /// to map [ServerException] to domain-specific failures. Otherwise, defaults
  /// to [InfrastructureFailure.server].
  ///
  /// Parameters:
  /// - [operation]: The async operation to execute (a data source call)
  ///
  /// Returns:
  /// - [Right(T)] if operation succeeds
  /// - [Left(Failure)] if operation fails
  ///
  /// Example:
  /// ```dart
  /// @override
  /// Future<Either<Failure, User>> login(Credentials creds) =>
  ///   execute(() async {
  ///     final result = await _remoteDataSource.login(creds);
  ///     await _tokenStorage.save(result.tokens);
  ///     return result.user.toDomain();
  ///   }

abstract class BaseRemoteDataSource {
  const BaseRemoteDataSource();

  /// Executes a data source operation with
  /// automatic error-to-exception conversion.
  ///
  /// This method wraps the given [operation] with error handling logic,
  /// converting any [Error] types (e.g., JSON parsing errors) into
  /// [FormatException] so they can be properly handled upstream.
  ///
  /// Parameters:
  /// - [operation]: The async operation to execute
  /// (typically an API call + parsing)
  ///
  /// Returns:
  /// - The result of the operation if successful
  ///
  /// Throws:
  /// - [FormatException] if an [Error] occurs during the operation
  /// - Any [Exception] thrown by the operation (passes through unchanged)
  @protected
  Future<T> execute<T>(Future<T> Function() operation) async {
    try {
      return await operation();
    } on Exception {
      // Exceptions should pass through unchanged
      rethrow;
    } catch (e, stackTrace) {
      // Convert any Error types to FormatException
      throw FormatException(
        'Data parsing failed: ${e.runtimeType}: $e\n'
        'Stack trace:\n$stackTrace',
      );
    }
  }

class CertificateService implements ICertificateService {
  CertificateService(this._logger);

  final IAppLogger _logger;

  /// content of the trusted certificate in bytes.
  List<int>? _trustedCertificateBytes;

  /// Returns the trusted certificate bytes.
  ///
  /// Returns null if:
  /// - Service hasn't been initialized
  /// - Certificate file wasn't found
  /// - SSL pinning is disabled/not configured
  @override
  List<int>? get trustedCertificateBytes => _trustedCertificateBytes;

  /// Initializes the service by loading the certificate from assets.
  ///
  /// Should be called during app bootstrap.
  @override
  Future<void> initialize() async {
    try {
      // In a real scenario, you might load this path from config
      // or try multiple common names.
      const certPath = 'assets/certificates/server.pem';

      try {
        final byteData = await rootBundle.load(certPath);
        _trustedCertificateBytes = byteData.buffer.asUint8List();
        _logger.info(
          'SSL certificate loaded successfully',
          tag: 'CertificateService',
        );
      } catch (e) {
        // It's okay if the file is missing in Dev, but we log it.
        if (e.toString().contains('Unable to load asset') ||
            e.toString().contains('not found')) {
          _logger.info(
            '''No SSL certificate found at $certPath. Pinning will be disabled if requested.''',
            tag: 'CertificateService',
          );
        } else {
          rethrow;
        }
      }
    } on Exception catch (e, stack) {
      _logger.error(
        'Failed to load SSL certificate',
        error: e,
        stackTrace: stack,
        tag: 'CertificateService',
      );
    }
  }

